def generate_typescript_file():
    total_count = sum(len(v) for v in STATES_DATA.values())
    print(f"Total States/UTs: {len(STATES_DATA)}")
    print(f"Total RTO Offices compiled: {total_count}")

    ts_lines = [
        "export interface RtoOfficeItem {",
        "  code: string;",
        "  name: string;",
        "  state: string;",
        "  city: string;",
        "  address: string;",
        "  pincode: string;",
        "  phone: string;",
        "  email: string;",
        "  timings: string;",
        "  lunchTime: string;",
        "  jurisdiction: string[];",
        "  lat: number;",
        "  lon: number;",
        "}",
        "",
        "export interface RtoFormItem {",
        "  formNo: string;",
        "  title: string;",
        "  category: string;",
        "  purpose: string;",
        "  requiredDocs: string[];",
        "  pdfUrl: string;",
        "}",
        "",
        "export const ALL_INDIA_RTO_OFFICES: RtoOfficeItem[] = [",
    ]

    for state_name, offices in STATES_DATA.items():
        ts_lines.append(f"  // ==================== {state_name.upper()} ({len(offices)} RTOs) ====================")
        for off in offices:
            code, name, city, address, pincode, phone, email, lat, lon, juris = off
            juris_json = json.dumps(juris)
            ts_lines.append("  {")
            ts_lines.append(f"    code: '{code}',")
            ts_lines.append(f"    name: {json.dumps(name)},")
            ts_lines.append(f"    state: {json.dumps(state_name)},")
            ts_lines.append(f"    city: {json.dumps(city)},")
            ts_lines.append(f"    address: {json.dumps(address)},")
            ts_lines.append(f"    pincode: '{pincode}',")
            ts_lines.append(f"    phone: '{phone}',")
            ts_lines.append(f"    email: '{email}',")
            ts_lines.append("    timings: '10:00 AM - 05:00 PM (Mon - Fri)',")
            ts_lines.append("    lunchTime: '01:30 PM - 02:00 PM',")
            ts_lines.append(f"    jurisdiction: {juris_json},")
            ts_lines.append(f"    lat: {lat},")
            ts_lines.append(f"    lon: {lon},")
            ts_lines.append("  },")

    ts_lines.extend([
        "];",
        "",
        "export function calculateDistanceKm(lat1: number, lon1: number, lat2: number, lon2: number): number {",
        "  const R = 6371; // Earth's radius in km",
        "  const dLat = ((lat2 - lat1) * Math.PI) / 180;",
        "  const dLon = ((lon2 - lon1) * Math.PI) / 180;",
        "  const a =",
        "    Math.sin(dLat / 2) * Math.sin(dLat / 2) +",
        "    Math.cos((lat1 * Math.PI) / 180) *",
        "      Math.cos((lat2 * Math.PI) / 180) *",
        "      Math.sin(dLon / 2) *",
        "      Math.sin(dLon / 2);",
        "  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));",
        "  return Math.round(R * c * 10) / 10;",
        "}",
        "",
    ])

    # Find frontend directory relative to this script
    script_dir = os.path.dirname(os.path.abspath(__file__))
    target_path = os.path.normpath(os.path.join(script_dir, '../../frontend/src/data/rtoOfficesData.ts'))
    
    with open(target_path, 'w', encoding='utf-8') as f:
        f.write("\n".join(ts_lines))

    print(f"Successfully written to {target_path}!")

if __name__ == '__main__':
    generate_typescript_file()
